def transform(grid):
 g=[row[:] for row in grid]
 start=next(( (r,c) for r,row in enumerate(g) for c,v in enumerate(row) if v==2),None)
 if start is None:return g
 r,c=start
 barriers=[i for i,row in enumerate(g) if 8 in row and i>r]
 for rr in barriers:
  holes=[j for j,v in enumerate(g[rr]) if v==0]
  for j in holes:g[rr][j]=2
  if rr==barriers[0]: a,b=min(c,holes[0]),max(c,holes[0])
  else:a,b=min(holes),max(holes)
  for j in range(a,b+1):
   if g[rr-1][j]==0:g[rr-1][j]=2
 return g
